def check_n(n, limit=1000):
    for y1 in range(2, limit):
        for y2 in range(2, limit):
            y = [0] * (n + 1)
            y[1] = y1
            y[2] = y2
            possible = True
            for i in range(2, n):
                # y[i+1] * y[i-1] = y[i]**2 - 2*y[i] + 2
                num = y[i]**2 - 2*y[i] + 2
                if num % y[i-1] == 0:
                    y[i+1] = num // y[i-1]
                    if y[i+1] < 2:
                        possible = False
                        break
                else:
                    possible = False
                    break
            if possible:
                return True, y[1:]
    return False, None

for n in range(3, 7):
    res, seq = check_n(n)
    print(f"n={n}: {res}, seq={seq}")

