    for y2 in range(2, limit):
        for y3 in range(2, limit):
            # y1 = (y2^2 - 2*y2 + 2) / y3
            num1 = y2**2 - 2*y2 + 2
            if num1 % y3 == 0:
                y1 = num1 // y3
                if y1 >= 2:
                    # y4 = (y3^2 - 2*y3 + 2) / y2
