def has_only_allowed_factors(n):
    if n < 1: return False
    if n == 1: return True
    # check factor 2
    while n % 2 == 0:
        n //= 2
    # check factors 4k+1
    # we only need to check up to sqrt(n)
    d = 3
    while d * d <= n:
        if n % d == 0:
            if d % 4 != 1:
                return False
            while n % d == 0:
                n //= d
        d += 2
    if n > 1:
        if n % 4 != 1:
            return False
    return True

