def search_n5_final(y1_limit=10000):
    for y1 in range(2, y1_limit):
        # y2 must be a divisor of 2*(y1-1)**2 + 2
        target = 2 * (y1 - 1)**2 + 2
        divisors = []
        for d in range(1, int(target**0.5) + 1):
            if target % d == 0:
                divisors.append(d)
                divisors.append(target // d)

        for y2 in divisors:
            if y2 < 2: continue
            # Now we check if y3, y4, y5 are integers
            num3 = (y2 - 1)**2 + 1
            if num3 % y1 == 0:
                y3 = num3 // y1
                if y3 < 2: continue
                num4 = (y3 - 1)**2 + 1
                if num4 % y2 == 0:
                    y4 = num4 // y2
                    if y4 < 2: continue
                    num5 = (y4 - 1)**2 + 1
                    if num5 % y3 == 0:
                        y5 = num5 // y3
                        if y5 >= 2:
                            return True, (y1, y2, y3, y4, y5)
    return False, None

print(f"n=5 final search: {search_n5_final()}")

def check_n_fixed(n, limit=1000):
    for x1 in range(1, limit):
        for x2 in range(1, limit):
            x = [0] * (n + 1)
            x[1] = x1
            x[2] = x2
            possible = True
            for i in range(2, n):
                num = x[i]**2 - x[i-1]
                den = x[i-1] + 1
                if num % den == 0:
                    x[i+1] = num // den
                    if x[i+1] <= 0:
                        possible = False
                        break
                else:
                    possible = False
                    break
            if possible:
                return True, x[1:]
    return False, None

